    public KdAtom findAtomByIndex(final int n) {
        this.checkTable();
        for (final KdAtom kdAtom : this.atoms) {
            if (kdAtom.index == n) {
                return kdAtom;
            }
        }
        return null;
    }
    
    public KdAtom findAtomByName(final String s) {
        this.checkTable();
        for (final KdAtom kdAtom : this.atoms) {
            if (kdAtom.name.equals((Object)s)) {
                return kdAtom;
            }
        }
        return null;
    }
